-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): fdp capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- INTERMEDIATE
--   Fields read with the switch on: ukot_uk01_well_cost_usd,
--   ukot_campaign_cost_usd, ukot_platform_capex_mm,
--   ukot_platform_decommissioning_mm.
--   The Wells table prints well cost in $MM at 1 decimal (a 37500 USD miss) and
--   the facility cards $MM at 1 decimal.
--   APPENDED: Read the figures in the FDP Accelerator with its Full precision
--   switch on (at the top of the page): it prints them to the precision this
--   capstone grades, with no digit grouping.
--
-- ADVANCED
--   Fields read with the switch on: meren_planned_value_usd, meren_spi.
--   Project Management Pro pinned the as-of to today, so neither planned value
--   nor SPI at 2030-03-31 could be read; SPI printed at 2 decimals.
--   APPENDED: Read the figures in the Project Management Pro studio and the FDP
--   Accelerator with their Full precision switch on (at the top of each page):
--   they print them to the precision this capstone grades, with no digit
--   grouping. In Project Management Pro, type the as-of date above into the As
--   of box in the header first.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/fdp.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- fdp / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'fdp' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 fdp refused: fdp/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'ca1ef66e1e88e3a81f883ef10b3ee50f' and fields = '[{"key": "ukot_network_duration_days", "tol": 0.5, "unit": "days", "label": "Duration of the schedule network, from its dependencies and durations", "expected": 671}, {"key": "ukot_calendar_span_days", "tol": 0.5, "unit": "days", "label": "Calendar span between the earliest start date and the latest end date typed on the activities", "expected": 764}, {"key": "ukot_uk01_well_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of UK-01 at the stated rig rate, services included", "expected": 37762500}, {"key": "ukot_campaign_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of all three wells at the stated rig rate, services included", "expected": 86125000}, {"key": "ukot_platform_capex_mm", "tol": 0.01, "unit": "million USD", "label": "Screening capex of Ukot platform at its nameplate", "expected": 743.1213581482968}, {"key": "ukot_platform_decommissioning_mm", "tol": 0.01, "unit": "million USD", "label": "Screening decommissioning cost of Ukot platform at its nameplate", "expected": 111.46820372224452}]'::jsonb then 'old'
              when md5(prompt) = 'b4f6a74a8d6564ec79431367bd3e6393' and fields = '[{"key": "ukot_network_duration_days", "tol": 0.5, "unit": "days", "label": "Duration of the schedule network, from its dependencies and durations", "expected": 671}, {"key": "ukot_calendar_span_days", "tol": 0.5, "unit": "days", "label": "Calendar span between the earliest start date and the latest end date typed on the activities", "expected": 764}, {"key": "ukot_uk01_well_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of UK-01 at the stated rig rate, services included", "expected": 37762500}, {"key": "ukot_campaign_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of all three wells at the stated rig rate, services included", "expected": 86125000}, {"key": "ukot_platform_capex_mm", "tol": 0.01, "unit": "million USD", "label": "Screening capex of Ukot platform at its nameplate", "expected": 743.1213581482968}, {"key": "ukot_platform_decommissioning_mm", "tol": 0.01, "unit": "million USD", "label": "Screening decommissioning cost of Ukot platform at its nameplate", "expected": 111.46820372224452}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'fdp' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w3 fdp refused: fdp/intermediate matches neither its post-W1 form (prompt md5 ca1ef66e1e88e3a81f883ef10b3ee50f) nor its W3 form (prompt md5 b4f6a74a8d6564ec79431367bd3e6393), with the fields this file was generated against';
  end if;

  -- fdp / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'fdp' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 fdp refused: fdp/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '08e1e87fc4b4a32df93f8e095b1e0057' and fields = '[{"key": "meren_planned_value_usd", "tol": 1, "unit": "USD", "label": "Planned value of the project as of 2030-03-31", "expected": 8205591.467356173}, {"key": "meren_earned_value_usd", "tol": 1, "unit": "USD", "label": "Earned value of the project as of 2030-03-31", "expected": 6480000}, {"key": "meren_spi", "tol": 0.00001, "unit": "ratio", "label": "Schedule performance index as of 2030-03-31", "expected": 0.7897054131660108}, {"key": "meren_completion_ratio", "tol": 0.00001, "unit": "ratio", "label": "Earned value over the budget at completion", "expected": 0.2745762711864407}, {"key": "ukot_price_swing_mm", "tol": 0.05, "unit": "million USD", "label": "Swing in NPV between the minus 30 percent and plus 30 percent oil price cases of the sensitivity sweep, on the plan cost items", "expected": 2206.7509870934814}, {"key": "ukot_stress_npv_mm", "tol": 0.05, "unit": "million USD", "label": "NPV of the Low case scenario on the Wellhead platform concept", "expected": -797.9291563861506}]'::jsonb then 'old'
              when md5(prompt) = 'af6dd18a511aa7e33032f6335b0c8975' and fields = '[{"key": "meren_planned_value_usd", "tol": 1, "unit": "USD", "label": "Planned value of the project as of 2030-03-31", "expected": 8205591.467356173}, {"key": "meren_earned_value_usd", "tol": 1, "unit": "USD", "label": "Earned value of the project as of 2030-03-31", "expected": 6480000}, {"key": "meren_spi", "tol": 0.00001, "unit": "ratio", "label": "Schedule performance index as of 2030-03-31", "expected": 0.7897054131660108}, {"key": "meren_completion_ratio", "tol": 0.00001, "unit": "ratio", "label": "Earned value over the budget at completion", "expected": 0.2745762711864407}, {"key": "ukot_price_swing_mm", "tol": 0.05, "unit": "million USD", "label": "Swing in NPV between the minus 30 percent and plus 30 percent oil price cases of the sensitivity sweep, on the plan cost items", "expected": 2206.7509870934814}, {"key": "ukot_stress_npv_mm", "tol": 0.05, "unit": "million USD", "label": "NPV of the Low case scenario on the Wellhead platform concept", "expected": -797.9291563861506}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'fdp' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w3 fdp refused: fdp/advanced matches neither its post-W1 form (prompt md5 08e1e87fc4b4a32df93f8e095b1e0057) nor its W3 form (prompt md5 af6dd18a511aa7e33032f6335b0c8975), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w3 fdp: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 fdp refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'The UKOT schedule, finish to start: u1 Sanction: 0 days, nothing before it, dated 2028-06-01 to 2028-06-01; u2 Jacket fabrication: 260 days, after u1, dated 2028-06-02 to 2029-02-16; u3 Topsides fabrication: 380 days, after u1, dated 2028-06-02 to 2029-06-16; u4 Flowline procurement: 190 days, after u1, dated 2028-06-02 to 2028-12-08; u5 Offshore installation: 120 days, after u2, u3, dated 2029-06-17 to 2029-10-14; u6 Hook up and commissioning: 171 days, after u5, dated 2029-10-15 to 2030-04-03; u7 First production: 0 days, after u4, u6, dated 2030-07-05 to 2030-07-05. Wells at a rig rate of 265000 USD a day with services at 1.5 times the rig: UK-01 Horizontal, measured depth 13100 ft; UK-02 Deviated, measured depth 10400 ft; UK-03 Vertical, measured depth 8700 ft. Facilities: Ukot platform (Platform), nameplate 45000 bopd; Ukot platform, expanded (Platform), nameplate 110000 bopd. Read six values. Days as whole numbers; well costs to the nearest USD; facility money to four decimals in million USD. Read the figures in the FDP Accelerator with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'fdp' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 fdp refused: fdp/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'b4f6a74a8d6564ec79431367bd3e6393' and fields = '[{"key": "ukot_network_duration_days", "tol": 0.5, "unit": "days", "label": "Duration of the schedule network, from its dependencies and durations", "expected": 671}, {"key": "ukot_calendar_span_days", "tol": 0.5, "unit": "days", "label": "Calendar span between the earliest start date and the latest end date typed on the activities", "expected": 764}, {"key": "ukot_uk01_well_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of UK-01 at the stated rig rate, services included", "expected": 37762500}, {"key": "ukot_campaign_cost_usd", "tol": 1, "unit": "USD", "label": "Drilling cost of all three wells at the stated rig rate, services included", "expected": 86125000}, {"key": "ukot_platform_capex_mm", "tol": 0.01, "unit": "million USD", "label": "Screening capex of Ukot platform at its nameplate", "expected": 743.1213581482968}, {"key": "ukot_platform_decommissioning_mm", "tol": 0.01, "unit": "million USD", "label": "Screening decommissioning cost of Ukot platform at its nameplate", "expected": 111.46820372224452}]'::jsonb) from public.academy_capstones where app_slug = 'fdp' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 fdp refused: fdp/intermediate does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'MEREN-3, a project schedule in the Project Management Pro studio, in USD, read as of 2030-03-31: Concept select: planned cost 1800000, actual cost 1950000, 100 percent complete, planned 2029-02-01 to 2029-07-31; Define and FEED: planned cost 4600000, actual cost 2860000, 70 percent complete, planned 2029-06-01 to 2030-05-31; Equipment orders: planned cost 7300000, actual cost 1180000, 20 percent complete, planned 2029-11-01 to 2030-12-31; Site construction: planned cost 9900000, actual cost 0, 0 percent complete, planned 2030-07-01 to 2031-09-30. The UKOT field development plan in the FDP Accelerator (plan money in million USD). Reserves: Ukot North (Oil): P90 48, P50 82, P10 130; Ukot South (Oil): P90 17, P50 29, P10 47; Ukot Shallow Gas (Gas): P90 26, P50 46, P10 73; Ukot Deep Gas (Gas): P90 15, P50 28, P10 45. Concepts: Wellhead platform (Platform): drilling capex 410, facilities capex 760, subsea capex 150, operating cost 68 a year, field life 18 years, peak production 44 kbpd, start date 2028-06-01; Extended tie-back (Subsea Tie-back): drilling capex 190, facilities capex 120, subsea capex 260, operating cost 33 a year, field life 14 years, peak production 19 kbpd, start date 2028-06-01. Scenarios on the Wellhead platform concept: Board case at 68 USD a barrel and Low case at 22 USD a barrel, both discounted at 10 percent, on the engine''s default royalty and tax. Cost items: Development wells (CAPEX) 410; Platform jacket and topsides (CAPEX) 760; Flowlines and umbilicals (CAPEX) 150; Operations (OPEX) 44; Integrity and inspection (OPEX) 24; Abandonment provision (ABEX) 190. Read six values. USD to the nearest unit; ratios to six decimals; plan money to four decimals in million USD. Read the figures in the Project Management Pro studio and the FDP Accelerator with their Full precision switch on (at the top of each page): they print them to the precision this capstone grades, with no digit grouping. In Project Management Pro, type the as-of date above into the As of box in the header first.'
     where app_slug = 'fdp' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 fdp refused: fdp/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'af6dd18a511aa7e33032f6335b0c8975' and fields = '[{"key": "meren_planned_value_usd", "tol": 1, "unit": "USD", "label": "Planned value of the project as of 2030-03-31", "expected": 8205591.467356173}, {"key": "meren_earned_value_usd", "tol": 1, "unit": "USD", "label": "Earned value of the project as of 2030-03-31", "expected": 6480000}, {"key": "meren_spi", "tol": 0.00001, "unit": "ratio", "label": "Schedule performance index as of 2030-03-31", "expected": 0.7897054131660108}, {"key": "meren_completion_ratio", "tol": 0.00001, "unit": "ratio", "label": "Earned value over the budget at completion", "expected": 0.2745762711864407}, {"key": "ukot_price_swing_mm", "tol": 0.05, "unit": "million USD", "label": "Swing in NPV between the minus 30 percent and plus 30 percent oil price cases of the sensitivity sweep, on the plan cost items", "expected": 2206.7509870934814}, {"key": "ukot_stress_npv_mm", "tol": 0.05, "unit": "million USD", "label": "NPV of the Low case scenario on the Wellhead platform concept", "expected": -797.9291563861506}]'::jsonb) from public.academy_capstones where app_slug = 'fdp' and tier = 'advanced' and active) is not true then
    raise exception 'w3 fdp refused: fdp/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 fdp: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
